from pathlib import Path
import difflib
import html
import json
import re

import markdown

OUT = Path(__file__).resolve().parent
ROOT = OUT.parents[3]
STARTER = ROOT / 'doc/book/studies/ada-xr-starter'
MAP = ROOT / 'commons/maps/Primitives_Ignorance'
prose = (MAP / 'tutorial.md').read_text(encoding='utf-8')
octahedron = (STARTER / 'studies/primitive_rules/octahedron.gd').read_text(encoding='utf-8')
sphere = (STARTER / 'studies/primitive_rules/sphere.gd').read_text(encoding='utf-8')
blocks = re.findall(r'```gdscript\n(.*?)```', prose, re.S)
assert len(blocks) == 3
assert all(block.strip() in octahedron for block in blocks[:2])
assert blocks[2].strip() in sphere
assert all('$' not in s and 'get_node' not in s for s in [octahedron, sphere])
report = json.loads((OUT / 'verification.json').read_text(encoding='utf-8'))
assert report['passed'] and all(c['passed'] for c in report['checks'])
assert (MAP / 'tutorial-museum.md').read_bytes() == (OUT / 'before/tutorial.md').read_bytes()
before = (OUT / 'before/tutorial.md').read_text(encoding='utf-8')
(OUT / 'tutorial.md').write_text(prose, encoding='utf-8')
(OUT / 'octahedron.gd').write_text(octahedron, encoding='utf-8')
(OUT / 'sphere.gd').write_text(sphere, encoding='utf-8')
(OUT / 'tutorial.diff').write_text(''.join(difflib.unified_diff(before.splitlines(True), prose.splitlines(True), fromfile='before/tutorial.md', tofile='tutorial.md')), encoding='utf-8')
reading = markdown.markdown(prose.replace('../../../doc/book/studies/ada-xr-starter/README.md', '../../studies/ada-xr-starter/README.md'), extensions=['fenced_code'])

def figure(name, alt, caption):
    return f'<figure><a href="{name}"><img src="{name}" alt="{alt}"></a><figcaption>{caption}</figcaption></figure>'

room = figure('room.png', 'Six numbered octahedron corners beside a SphereMesh whose triangle edges are drawn in black.', 'The running student room. Left: positions from a short rule. Right: geometry generated by SphereMesh.')
reading = reading.replace('<h2>1. Give a rule a name</h2>', room + '<h2>1. Give a rule a name</h2>')
pair = '<div class="pair">' + figure('radius.png', 'A larger regular octahedron beside the unchanged sphere.', 'Call the function with 0.75: all six corners move radially outward.') + figure('edited.png', 'The top octahedron corner moved sideways, changing its neighbouring faces.', 'Move one handle instead: the connections remain, the regularity does not.') + '</div>'
reading = reading.replace('<h2>4. Return to the sphere</h2>', pair + '<h2>4. Return to the sphere</h2>')
sphere_pair = '<div class="pair">' + figure('sphere-16-4.png', 'Sphere with sixteen radial segments and four rings.', '16 radial segments / 4 rings. More divisions around the axis.') + figure('sphere-8-8.png', 'Sphere with eight radial segments and eight rings.', '8 radial segments / 8 rings. More divisions along the height.') + '</div>'
reading = reading.replace('<p>SphereMesh generates its own positions', sphere_pair + '<p>SphereMesh generates its own positions')
checks = len(report['checks'])
page = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Primitives — a rule for positions</title><link rel="stylesheet" href="style.css"></head><body><main>
<header><nav><a href="#reading">Read the lesson</a><a href="#code">Complete code</a><a href="#scope">Lineage and scope</a><a href="#checked">Checks</a><a href="../2026-10-03-cube-a-shared-diagonal/index.html#reading">Previous: Cube</a></nav><p>ADA / TUTORIAL PILOT / 3 OCTOBER 2026</p></header>
<article id="reading">{reading}<p><a class="download" href="../2026-10-03-ada-xr-starter/ada-xr-starter.zip" download>Download the updated starter</a></p><p class="small">Open primitive_rules.tscn. Click an image for its full native render.</p></article>
<details id="code"><summary>Complete lesson scripts</summary><div><p>octahedron.gd generates positions and reuses the existing face-list renderer. The position function is the new learner-owned operation. Labels, input, edge strokes and materials are supplied.</p><pre><code>{html.escape(octahedron)}</code></pre><p>sphere.gd returns to Point One's resource. MeshEdges supplies an inspection guide from that resource's actual triangle geometry.</p><pre><code>{html.escape(sphere)}</code></pre><p><a href="octahedron.gd" download>Octahedron script</a> · <a href="sphere.gd" download>Sphere script</a> · <a href="tutorial.md">Tutorial source</a> · <a href="tutorial.diff">Text diff</a></p></div></details>
<details id="scope"><summary>From a position list to a function that returns one</summary><div><p>Trace introduced a list. Polyhedra separated positions from connections. Cube made one connection consequential. Now a small rule generates position data, and the learner edits its result. SphereMesh returns as a built-in generator with settings to inspect.</p><p>The type declaration describes the values crossing the function boundary; it does not prove regularity. A positive radius and the stated direction rule make the initial arrangement regular. Drawing and connectivity remain separate operations.</p><p>This tutorial selects two studies from the hall. Its capsule, pillars and other prefabs remain in the <a href="../../../../commons/maps/Primitives_Ignorance/tutorial-museum.md">preserved museum walkthrough</a>. No critical chapter or live placement was edited. Both lesson scripts create their own geometry and need no scene lookups.</p><p>The scene positions both studies in the prepared room; their internal coordinates remain local. These studies need no saved gesture and do not alter the earlier Trace. Coordinates still needs its earlier shared-starter pass. <a href="lesson-contract.json">Teaching contract</a> · <a href="DECISIONS.md">Decisions</a></p></div></details>
<details id="checked"><summary>{checks} native checks passed</summary><div><p>Cold import of a freshly extracted ZIP, correct opposite-axis positions, independent function results, actual printed edits, closed equilateral faces, persistent handle edits, changes in generated sphere geometry, agreement between wire guide and source, desktop mouse and synthetic XR grip, release and reset.</p><p>Three printed excerpts match the scripts. Screenshots are native Godot 4.6 renders from the student room. Physical headset use, Quest performance and beginner comprehension remain untested.</p><p><a href="verification.json">Results</a> · <a href="verify.gd">Reproducible harness</a> · <a href="package-verification.json">Download checks</a></p></div></details>
</main><script>function reveal(){{const el=document.getElementById(location.hash.slice(1));if(el?.tagName==='DETAILS')el.open=true}}addEventListener('hashchange',reveal);reveal();</script></body></html>'''
(OUT / 'index.html').write_text(page, encoding='utf-8')
print(json.dumps({'checks': checks, 'printed_code_excerpts': len(blocks), 'tutorial_words_including_code': len(prose.split())}))
